INSERT INTO `layanan_sosmed` (`id`, `service_id`, `id_kategori`, `kategori`, `layanan`, `catatan`, `average`, `min`, `max`, `harga`, `harga_api`, `profit`, `status`, `provider_id`, `provider`, `tipe`, `refill`) VALUES
(1, 1, '1', 'TikTok Comments', 'TikTok Emoji Comment | Max 5K | Instant Start | NO Drop | 1K/Hour [R30]', '⚠Catatan:\r\n    📌 Periksa format tautan dengan cermat sebelum melakukan pemesanan.\r\n    🔓 Mohon pastikan akun Anda bersifat publik, bukan pribadi.\r\n    📌 Saat layanan sibuk, kecepatan awal pengoperasian/speed services dapat berubah.\r\n    📌 Jangan melakukan pemesanan kedua pada link yang sama sebelum pesanan Anda selesai di sistem.', '0 hari 13 jam 56 menit 11 detik', 12, 30000, 165165, 150150, 15015, 'Aktif', 3158, 'ZAYNFLAZZ', 'Sosial Media', ''),
(2, 2, '2', 'TikTok Shares', 'TikTok Shares [Max: 10M] [Refill: 365 Days] [Start Time: 1 Min] [Speed: 1M/Day] ♻️', '⚠Catatan:\r\n    📌 Periksa format tautan dengan cermat sebelum melakukan pemesanan.\r\n    🔓 Mohon pastikan akun Anda bersifat publik, bukan pribadi.\r\n    📌 Saat layanan sibuk, kecepatan awal pengoperasian/speed services dapat berubah.\r\n    📌 Jangan melakukan pemesanan kedua pada link yang sama sebelum pesanan Anda selesai di sistem.', '0 hari 2 jam 12 menit 37 detik', 60, 10000000, 23595, 21450, 2145, 'Aktif', 2754, 'ZAYNFLAZZ', 'Sosial Media', ''),
(3, 3, '3', 'TikTok Views', 'TikTok Video Views | Non-Drop | Instant Start | 400M - 150M/Day	 ', '⚠Catatan:\r\n    📌 Periksa format tautan dengan cermat sebelum melakukan pemesanan.\r\n    🔓 Mohon pastikan akun Anda bersifat publik, bukan pribadi.\r\n    📌 Saat layanan sibuk, kecepatan awal pengoperasian/speed services dapat berubah.\r\n    📌 Jangan melakukan pemesanan kedua pada link yang sama sebelum pesanan Anda selesai di sistem.', '0 hari 11 jam 32 menit 19 detik', 120, 40000000, 165.165, 150.15, 15.015, 'Aktif', 2769, 'ZAYNFLAZZ', 'Sosial Media', ''),
(4, 4, '4', 'YouTube Shorts Views | Likes', '🔥YouTube Short Likes | NonDrop [Max 20K] ⏰Instant Start Daily 10K ♻️ [R30] 🔥', '⚠Catatan:\r\n    📌 Periksa format tautan dengan cermat sebelum melakukan pemesanan.\r\n    🔓 Mohon pastikan akun Anda bersifat publik, bukan pribadi.\r\n    📌 Saat layanan sibuk, kecepatan awal pengoperasian/speed services dapat berubah.\r\n    📌 Jangan melakukan pemesanan kedua pada link yang sama sebelum pesanan Anda selesai di sistem.', '0 hari 11 jam 1 menit 48 detik', 12, 50000, 18876, 17160, 1716, 'Aktif', 2460, 'ZAYNFLAZZ', 'Sosial Media', '1'),
